def solution(input_string):
    """
    Solve the disjoint triangles problem.
    """
    import sys
    from io import StringIO
    import tempfile

    # Parse input
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def choose3(k):
        if k < 3:
            return 0
        return k * (k - 1) * (k - 2) // 6

    # For each separating line, count points on each side
    # A separating line through points i, j divides remaining points
    total = 0
    seen_lines = set()

    for i in range(n):
        for j in range(i + 1, n):
            line_key = (tuple(sorted([i, j])))
            if line_key in seen_lines:
                continue
            seen_lines.add(line_key)

            # Find points on each side of line (i, j)
            left_count = 0
            right_count = 0

            for k in range(n):
                if k == i or k == j:
                    continue

                cp = cross_product(points[i], points[j], points[k])
                if cp > 0:
                    left_count += 1
                elif cp < 0:
                    right_count += 1

            # Points on left: i, j, left_count other points
            # Points on right: right_count points

            # Count triangles that use exactly {i, j} as base
            if right_count >= 3:
                # Triangle 2 from right side
                total += choose3(right_count)

    return str(total)
