def count_digits_1_to_n(n):
    """Calculate total digits needed to write numbers 1 to n."""
    if n <= 0:
        return 0

    total = 0
    num_digits = 1
    start = 1

    while start <= n:
        end = min(n, start * 10 - 1)
        count = end - start + 1
        total += count * num_digits
        start *= 10
        num_digits += 1

    return total


def get_block_and_offset(k):
    """Find which block k falls into and the offset within that block (1-indexed)."""
    cumulative = 0
    block = 0

    while True:
        block += 1
        block_len = count_digits_1_to_n(block)
        cumulative += block_len
        if k <= cumulative:
            offset = k - (cumulative - block_len)
            return block, offset


def find_digit_in_block(block, offset):
    """Find the digit at the given offset within block 'block'."""
    num = 1
    while True:
        num_str = str(num)
        num_len = len(num_str)

        if offset > 0:
            if offset <= num_len:
                return num_str[offset - 1]
            offset -= num_len
        else:
            break
        num += 1
    return '0'


