Looking at this problem, I need to solve a CNF satisfiability problem where each variable appears in at most 2 clauses. This is related to 2-SAT but with clauses that can have more than 2 literals. I'll implement a backtracking solution with early termination since the constraint guarantees it's tractable.

```python
import sys
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "NO"

    if n == 0:
        # Empty CNF is satisfiable
        return "YES\n" + '0' * m if m > 0 else "YES"

    clauses = []
    var_to_clauses = defaultdict(list)

    # Parse all clauses
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)
        for lit in literals:
            var = abs(lit)
            if var <= m:
                var_to_clauses[var].append(i - 1)

    # Assignment: 0 = unassigned, 1 = TRUE, -1 = FALSE
    assignment = [0] * (m + 1)

    def is_clause_satisfied(clause_idx):
        for lit in clauses[clause_idx]:
            var = abs(lit)
            if assignment[var] == 0:
                continue
            sign = 1 if lit > 0 else -1
            if assignment[var] == sign:
                return True
        return False

    def count_unsatisfied():
        return sum(1 for i in range(n) if not is_clause_satisfied(i))

    def backtrack(idx):
        # All variables assigned - check if all clauses satisfied
        if idx > m:
            return count_unsatisfied() == 0

        # Skip already assigned variables
        if assignment[idx] != 0:
            return backtrack(idx + 1)

        found = False
        # Try assigning TRUE
        for val in [1, -1]:
            assignment[idx] = val

            # Quick check for immediate unsatisfiability
            if count_unsatisfied() == n:  # All still unsatisfied
                assignment[idx] = 0
                continue

            # Prune if all assigned and still unsatisfied
            if idx > m - 5:  # Near end, check early
                if count_unsatisfied() > 0:
                    assignment[idx] = 0
                    continue

            result = backtrack(idx + 1)
            if result:
                found = True
                break

            assignment[idx] = 0

        return found

    # Try to find satisfying assignment
    if backtrack(1):
        result_string = ''.join('1' if assignment[i] == 1 else '0' for i in range(1, m + 1))
        return f"YES\n{result_string}"
    else:
        return "NO"
