3. Checks clause satisfaction after each assignment
4. Terminates early if a valid assignment is found (first solution is sufficient for SAT)

Looking at this problem, I need to solve it as a maximum flow problem where:
- Soldiers from each city must be distributed
- They can only move to adjacent cities (or stay)
- Each city must end up with exactly b[i] soldiers

I'll use Dinic's max flow algorithm to check feasibility and reconstruct the movement matrix.

```python
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v = map(int, lines[3 + i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Total soldiers from all cities
    total_soldiers = sum(a)

    # Build flow network
    # Source = 0, Cities = 1 to n, Sink = n + 1
    source, sink = 0, n + 1

    original_cap = [[0] * (n + 2) for _ in range(n + 2)]
    capacity = [[0] * (n + 2) for _ in range(n + 2)]

    # Source to each city with capacity = a[i]
    for i in range(n):
        original_cap[source][i + 1] = total_soldiers  # Data above
        original_cap[source][i + 1] = a[i]
        capacity[source][i + 1] = a[i]

    # Each city to sink with capacity = b[i]
    for i in range(n):
        original_cap[i + 1][sink] = b[i]
        capacity[i + 1][sink] = b[i]

    # City to city edges (including self-loops)
    # Capacity = large value if allowed movement
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or j in adj[i]:
                original_cap[i][j] = total_soldiers  # Large capacity
                capacity[i][j] = total_soldiers

    # Dinic's algorithm
    def bfs():
        level = [-1] * (n + 2)
        level[source] = 0
        queue = deque([source])
        while queue:
            u = queue.popleft()
            for v in range(n + 2):
                if capacity[u][v] > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level

    def dfs(u, flow, level, ptr):
        if u == sink:
            return flow
        for v in range(ptr[u], n + 2):
            ptr[u] = v
            if level[v] == level[u] + 1 and capacity[u][v] > 0:
                pushed = dfs(v, min(flow, capacity[u][v]), level, ptr)
                if pushed > 0:
                    capacity[u][v] -= pushed
                    capacity[v][u] += pushed
                    return pushed
        return 0

    # Compute max flow
    max_flow = 0
    while True:
        level = bfs()
        if level[sink] < 0:
            break
        ptr = [0] * (n + 2)
        while True:
            pushed = dfs(source, total_soldiers + 1, level, ptr)
            if pushed == 0:
                break
            max_flow += pushed

    if max_flow != total_soldiers:
        return "NO"

    # Reconstruct the movement matrix
    result = []
    for i in range(1, n + 1):
        row = []
        for j in range(1, n + 1):
            if i == j or j in adj[i - 1]:
                # Movement from i to j = original capacity - residual capacity
                movement = original_cap[i][j] - capacity[i][j]
                row.append(str(movement))
            else:
                row.append("0")
        result.append(' '.join(row))

    return "YES\n" + '\n'.join(result)
