                    # Merge reflected intervals
                    merged_reflected.sort()
                    merged_r = []
                    if merged_reflected:
                        start, end = merged_reflected[0]
                        for l, r in merged_reflected[1:]:
                            if l <= end:
                                end = max(end, r)
                            else:
                                merged_r.append((start, end))
                                start, end = l, r
                        merged_r.append((start, end))

                if merged_r:
                    merged_r.sort()
                    merged_rr = []
                    if merged_r:
                        start, end = merged_r[0]
                        for l, r in merged_r[1:]:
                            if l <= end:
                                end = max(end, r)
                            else:
                                merged_rr.append((start, end))
                                start, end = l, r
                        merged_rr.append((start, end))

                # Combine reflected and right intervals, compute union area
                all_intervals = merged_rr + merged_reflected
                if all_intervals:
                    all_intervals.sort()
                    all_merged = []
                    if all_intervals:
                        start, end = all_intervals[0]
                        for l, r in all_intervals[1:]:
                            if l <= end:
                                end = max(end, r)
                            else:
                                all_merged.append((start, end))
                                start, end = l, r
                        all_merged.append((start, end))

                    union_width = 0.0
                    for lst, rstd in all_merged:
                        union_width += max(rstd - lst, 0.0)

                    total_strip_area += union_width * (y_intervals[0][1] - y_intervals[0][0])

        results.append(f"{total_strip_area:.10f}")

    return "\n".join(results)
