    # full_cost[i][j] = cost for city i to connect to city j
    full_cost = [[0] * n for _ in range(n)]
    for i in range(n):
        vals = list(map(int, lines[i+1].split()))
        for j in range(n):
            if j == i:
                full_cost[i][j] = float('inf')
            else:
                # vals is missing column i, so adjust index
                col = j - 1 if j < i else j
                full_cost[i][j] = vals[col]

    # Build preference lists for each city (sorted by cost, ascending)
    prefs = []
    for i in range(n):
        sorted_cities = sorted([j for j in range(n) if j != i], key=lambda x: full_cost[i][x])
        prefs.append(sorted_cities)

    def check_stable(match: List[int]) -> bool:
        """
        Check if the matching is stable.
        match[i] is the 1-indexed partner of city i.
        """
        for i in range(n):
            my_partner = match[i]
            # Check all cities i prefers over their current partner
            for j in prefs[i]:
                if j == my_partner:
                    continue
                # Find j's current partner
                j_partner = -1
                for k in range(n):
                    if match[k] == j:
                        j_partner = k
                        break

                if j_partner == -1:
                    continue

                # Check if j also prefers i over their current partner
                if full_cost[j][i] < full_cost[j][j_partner]:
                    # Both prefer each other over current partners
                    return False
        return True

    # For small n, try all perfect matchings with randomization
    if n <= 8:
        from itertools import permutations

        for _ in range(min(10000, 3 * (n - 1))):
            # Try a different permutation ordering
            perm = list(range(n))
