            # Create matching from permutation
            match = [-1] * n
            for i in range(n // 2):
                a = perm[2*i]
                b = perm[2*i+1]
                match[a] = b + 1
                match[b] = a + 1

            if check_stable(match):
                return '\n'.join(map(str, [match[i] for i in range(n)]))

    # Try random search for larger n
    import random
    result = None

    for _ in range(min(50000, n * n * 10)):
        match = [-1] * n
        pool = list(range(n))
        random.shuffle(pool)

        used = [False] * n
        for i in range(n - 1):
            j = random.choice(pool)
            pool.remove(j)
            if used[i] or used[j]:
                continue
            match[i] = j + 1
            match[j] = i + 1
            used[i] = True
            used[j] = True

        if check_stable(match):
            result = match
            break

    if result is not None:
        return '\n'.join(map(str, [result[i] for i in range(n)]))
    else:
        return "-1"


