def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    if n < 3:
        return "0\n"

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def do_intersect(p1, q1, p2, q2):
        d1 = cross_product(p2, q2, p1)
        d2 = cross_product(p2, q2, q1)
        d3 = cross_product(p1, q1, p2)
        d4 = cross_product(p1, q1, q2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        if d1 == 0 and on_segment(p1, p2, q2): return True
        if d2 == 0 and on_segment(q1, p2, q2): return True
        if d3 == 0 and on_segment(p2, p1, q1): return True
        if d4 == 0 and on_segment(q2, p1, q1): return True
        return False

    def is_valid_diagonal(i, j, n):
        if abs(i - j) <= 1 or (i == 0 and j == n - 1):
            return True

        p1, p2 = points[i], points[j]
        for k in range(n):
            p3, p4 = points[k], points[(k + 1) % n]
            if (p1 == p3 and p2 == p4) or (p1 == p4 and p2 == p3):
                continue
            if do_intersect(p1, p2, p3, p4):
                return False
        return True

    def is_degenerate_triangle(p0, p1, p2):
        return cross_product(p0, p1, p2) == 0

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n
            k_count = 0
            if length == 2:
                k_count = 1
            else:
                for k in range(i + 1, j):
                    if not is_degenerate_triangle(points[i], points[k], points[j]):
                        continue
                    if not is_valid_diagonal(i, k, n) or not is_valid_diagonal(k, j, n):
                        continue
                    k_count += 1

            if k_count == 0:
                dp[i][j] = k_count
            else:
                if length == 2:
                    dp[i][j] = 1
                else:
                    for k in range(i + 1, j):
                        if not is_degenerate_triangle(points[i], points[k], points[j]):
                            continue
                        if not is_valid_diagonal(i, k, n) or not is_valid_diagonal(k, j, n):
                            continue
                        dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    return str(dp[0][n - 1]) + '\n'
