import sys

MOD = 998244353

def power(a, b):
    result = 1
    a %= MOD
    while b > 0:
        if b & 1:
            result = result * a % MOD
        a = a * a % MOD
        b >>= 1
    return result

def inverse(n):
    return power(n, MOD - 2)

def precompute_factorial(n):
    fact = [1] * (n + 1)
    invFact = [1] * (n + 1)

    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invFact[n] = inverse(fact[n])
    for i in range(n - 1, -1, -1):
        invFact[i] = invFact[i + 1] * (i + 1) % MOD

    return fact, invFact

def nCr(n, r, fact, invFact):
    if r < 0 or r > n:
        return 0
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD

def solution(input_str):
    n_k_l = input_str.strip().split()
    if len(n_k_l) < 1:
        return "0"

    n, k, l = int(n_k_l[0]), int(n_k_l[1]), int(n_k_l[2])

    if k > n or n < 1 or l < 1:
        return "0"

    MAX = 2 * n + 5
    fact, invFact = precompute_factorial(MAX)

    # Formula: E = l * C(n,k) * C(2n-k, n-k) / C(2n+1, k+1)
    num = nCr(n, k, fact, invFact) * nCr(2*n - k, n - k, fact, invFact) % MOD
    den = nCr(2*n + 1, k + 1, fact, invFact) % MOD

    if den == 0:
        return "0"

    result = l % MOD
    result = result * num % MOD
    result = result * inverse(den) % MOD

    return str(result)
