import sys
from collections import deque

sys.setrecursionlimit(300000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return "NO\n"

    n, m = map(int, lines[0].split())

    # Minimum requirements
    if n < 2 or m < 3:
        return "NO\n"

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i + len(lines) >= len(lines):
            continue
        line = lines[i] if i < len(lines) else ""
        if line.strip():
            parts = line.strip().split()
            if len(parts) >= 2:
                u, v = map(int, parts)
                adj[u].append(v)
                adj[v].append(u)

    def find_paths_bfs(s, t, max_paths):
        """Find up to max_paths internally vertex-disjoint paths from s to t"""
        paths = []
        tried_second_node = set()

        for _ in range(max_paths):
            if len(tried_second_node) >= len(adj[s]):
                break

            # All nodes visited track per path to ensure internal node disjointness
            path_visited = {s}
            queue = deque()
            queue.append((s, [s]))
            path_found = False

            while queue and not path_found:
                u, path = queue.popleft()

                if u == t:
                    # Valid path found
                    paths.append(path)
                    path_found = True
                    path_visited = {s}
                    queue = deque()
                else:
                    # Try neighbors, avoiding the second-to-last node
                    for v in adj[u]:
                        if v != path[-2] and v not in path_visited and v != s:
                            path_visited.add(v)
                            queue.append((v, path + [v]))

            if path_found:
                continue
            else:
                # Mark second node from path to avoid trying again soon
                # Then try a different second node
                if queue and len(queue) > 0:
                    neighbor = queue[-1][-1]
                    tried_second_node.add(neighbor)
                    continue

                break

        return paths

    # Try nodes with high degree first
    deg_nodes = []
    for u in range(1, n + 1):
        deg_nodes.append((len(adj[u]), u))
    deg_nodes.sort(reverse=True)
    deg_nodes = [d for d in deg_nodes if d[0] >= 3]

    # Try all high-degree pairs
    for i in range(len(deg_nodes)):
        for j in range(i + 1, len(deg_nodes)):
            s, t = deg_nodes[i][1], deg_nodes[j][1]
            paths = find_paths_bfs(s, t, 3)

            if len(paths) >= 3:
                output = ["YES"]
                for p in paths[:3]:
                    nodes_str = " ".join(map(str, p))
                    output.append(f"{len(p)} {nodes_str}")
                return "\n".join(output) + "\n"

    return "NO\n"


